const batchSize = 15;
const out = [];
for (let i = 0; i < items.length; i += batchSize) {
  out.push({
    json: {
      batch: items.slice(i, i + batchSize).map((it, idx) => ({
        ...it.json,
        _globalIndex: i + idx
      }))
    }
  });
}
return out;

/*****************************************************************
 *  BuildPrompt — hafif kopya + tam satır
 *  Başlıklar müşterinin nihai listesiyle bire bir
 *****************************************************************/

/* 1) Prompt’a gidecek hafif kopya  */
function slim (r) {
  return {
    idx : r._globalIndex,           // dahili sıra

    // ─ Kimlik (opsiyonel) ─
    sku : r["KOD"],

    // ─ Satış miktarları ─
    s45  : Number(r["Son 45 Satis Miktar"]   || 0),
    s90  : Number(r["Son 90 Satis Miktar"]   || 0),
    s180 : Number(r["Son 180 Satis Miktar"]  || 0),

    // ─ Giriş / alış miktarları ─
    g45  : Number(r["Son 45 Giris Miktar"]   || 0),
    g90  : Number(r["Son 90 Giris Miktar"]   || 0),
    g180 : Number(r["Son 180 Giris Miktar"]  || 0),

    // ─ Stoklar ─
    dep       : Number(r["DEPO"]                  || 0),
    mgzAra    : Number(r["MGZ GLN ARA DEPO"]      || 0),
    tplDepo   : Number(r["TPL DEPO"]              || 0),
    tplMgz    : Number(r["TPL MGZ"]               || 0),
    mkl       : Number(r["MKL"]                   || 0),
    bklSevk   : Number(r["BKLNYN MGZ SEVK"]       || 0),

    // ─ 9 mağaza stoku (SRN … MGL) ─
    SRN : Number(r["SRN"] || 0),
    BZK : Number(r["BZK"] || 0),
    HTY : Number(r["HTY"] || 0),
    NKT : Number(r["NKT"] || 0),
    ÜÇK : Number(r["ÜÇK"] || 0),
    GZM : Number(r["GZM"] || 0),
    TRB : Number(r["TRB"] || 0),
    MGL : Number(r["MGL"] || 0),
    FRB : Number(r["FRB"] || 0)
  };
}

/* 2) Model’e gidecek data */
const products = $json.batch.map(slim);

/* 3) MapBack için tam satırı sakla */
const batchWithFull = $json.batch.map(r => ({ fullRow: r }));

/* 4) Çıkış */
return {
  json: {
    batch : batchWithFull,           // MapBack kullanacak
    prompt: JSON.stringify(products) // Model’e giden hafif kopya
  }
};

/*****************************************************************
 *  MapBack – AI çıktısını satırlara geri yazar
 *  ▸ her batch = 25 (veya 50) satır
 *  ▸ Loop’a un-wrapped satırları geri yollar
 *****************************************************************/

// BuildPrompt’tan gelen batch + tam satırlar
const srcBatches = $items("Code: BuildPrompt", 0);

const processedRows  = [];     // AB-AC eklenmiş tüm satırlar
const nextInputBatch = [];     // Loop’a geri gidecek ham satırlar

items.forEach((item, idx) => {

  // ── AI cevabını JSON dizisine çevir
  let txt = item.json.message.content.trim();
  if (txt.startsWith("```"))
    txt = txt.replace(/```json|```/g, "").trim();

  let ai = [];
  try { ai = JSON.parse(txt); } catch (e) { /* eksik / hatalı */ }

  // ── Kaynak satırlar (wrap.fullRow)
  const srcWrapped = srcBatches[idx].json.batch;          // [{ fullRow }]
  const srcRows    = srcWrapped.map(w => w.fullRow);      // gerçek satırlar

  // Loop’un sonraki turu için ham satırları ekle
  nextInputBatch.push(...srcRows);

  // ── Her satıra AB / AC yaz
  srcRows.forEach((row, i) => {
    const r = ai[i] || { need: 0, reason: "AI missing" };
    processedRows.push({
      ...row,
      AB: Math.round(r.need),
      AC: r.reason.trim(),
      _globalIndex: row._globalIndex
    });
  });
});

/*  Tek item döndür – Loop beklediği alanları görüyor  */
return [{
  json: {
    batch : nextInputBatch,   // BuildPrompt’un girdisi
    rows  : processedRows     // Reassemble için
  }
}];

// Loop bitince buraya 200 item gelir, her item.json.rows = 50 satır
const all = [];
items.forEach(it => all.push(...it.json.rows));

// _globalIndex’e göre sırala
all.sort((a,b)=>a._globalIndex - b._globalIndex);

return all;   // 10 000 satır (veya kaç satırsa) eksiksiz

all.forEach(row => { delete row._globalIndex });
